"""Reproduce M5-M7 evidence; all JSON reports are generated by harness/scripts."""
import copy
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

from lab9 import gate, variants
from lab9.eval import load_spec, run_eval
from lab9.mutation import EXPECTED

ROOT = Path(__file__).resolve().parents[1]
SPEC = ROOT / "config/metric_spec_v2.yaml"


def command(args, expected=0, require=None):
    result = subprocess.run([sys.executable, "-B", *args], cwd=ROOT, capture_output=True,
                            text=True, encoding="utf-8", env={**os.environ, "PYTHONUTF8": "1"})
    passed = result.returncode == expected and (require is None or require in result.stdout)
    print("PASS" if passed else "FAIL", " ".join(args), flush=True)
    if not passed:
        print(result.stdout, result.stderr, flush=True)
    return {"args": args, "exit_code": result.returncode, "expected": expected, "passed": passed,
            "stdout": result.stdout, "stderr": result.stderr}


def write_report(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n", encoding="utf-8")


def main():
    os.chdir(ROOT)
    variants.register()
    spec = load_spec(SPEC)
    base = json.loads(Path("reports/baseline_v2.json").read_text(encoding="utf-8"))
    steps = [command(["-m", "pytest", "-q", "-m", "student", "-o", "addopts=", "-k", "lab9", "-p", "no:cacheprovider"]),
             command(["-m", "lab9.evalset", "--v2"])]
    self_blocked, _ = gate.check(base, base, spec, spec)
    cases = []
    for shape, expected in EXPECTED.items():
        report = run_eval(shape, spec)
        write_report(Path(f"reports/eval_v2_{shape}.json"), report)
        blocked, lines = gate.check(report, base, spec, spec)
        got = "block" if blocked else "merge"
        cases.append({"shape": shape, "expected": expected, "got": got, "passed": expected == got,
                      "run_id": report["run_id"], "metrics": report["metrics"], "blocked": blocked, "lines": lines})
        print(shape, got, blocked, flush=True)
    steps.append(command(["-m", "lab9.mutation", "--spec", str(SPEC), "--baseline", "reports/baseline_v2.json",
                          "--base-spec", str(SPEC)], require="mutation score 3/3"))
    aa = command(["-m", "lab9.mutation", "--spec", str(SPEC), "--aa", "66,77,88,99,110"])
    steps.append(aa)
    aa_values = {}
    for line in aa["stdout"].splitlines()[1:]:
        parts = line.split()
        if len(parts) == 4:
            aa_values[parts[0]] = dict(zip(("first", "second", "delta"), map(float, parts[1:])))
    aa_zero = bool(aa_values) and all(v["delta"] == 0 for v in aa_values.values())
    steps.append(command(["-m", "lab9.traps", "--pr", "reports/eval_v2_slice_regression.json",
                          "--baseline", "reports/baseline_v2.json", "--spec", str(SPEC)]))
    trap_steps = []
    for name in ("evaluator_errors_as_nan", "dropped_failing_rows", "cherry_picked_seeds", "loosened_spec"):
        args = ["-m", "lab9.gate", "--pr", f"reports/traps/{name}.json", "--baseline", "reports/baseline_v2.json",
                "--spec", str(SPEC)]
        if name == "loosened_spec":
            args[-1] = f"reports/traps/{name}.spec.yaml"
            args += ["--base-spec", str(SPEC)]
        result = command(args, expected=1, require="INTEGRITY")
        result["name"] = name
        trap_steps.append(result)
    hidden_like = {}
    for name in ("duplicate_row", "evaluator_crash", "slice_relabel", "inflated_summary"):
        rep = copy.deepcopy(base)
        if name == "duplicate_row": rep["rows"][-1] = copy.deepcopy(rep["rows"][0])
        if name == "evaluator_crash": rep["evaluator_failures"] = ["simulated grader failure"]
        if name == "slice_relabel": rep["rows"][0]["slices"] = ["unknown_slice"]
        if name == "inflated_summary": rep["metrics"]["pass_rate"] = 1.0
        blocked, lines = gate.check(rep, base, spec, spec)
        hidden_like[name] = {"blocked": blocked, "lines": lines}
    artifacts = ["lab9/stats.py", "lab9/gate.py", "lab9/integrity.py", "lab9/graders.py",
                 "config/metric_spec_v2.yaml", "config/fm_map.yaml", "data/eval/eval_set_v2.jsonl",
                 "data/eval/labels_v2.json", "reports/baseline_v2.json"]
    output = {"run_id": datetime.now(timezone.utc).strftime("advanced-%Y%m%dT%H%M%SZ"),
              "recipe": "python -B -m tests.run_advanced_verification", "scope": "local; not remote GitHub Actions",
              "self_baseline_blocked": self_blocked, "variants": cases, "steps": steps,
              "aa": aa_values, "aa_zero": aa_zero, "traps": trap_steps, "extra_traps": hidden_like,
              "source_sha256_lf": {p: hashlib.sha256(Path(p).read_bytes().replace(b"\r\n", b"\n")).hexdigest()
                                    for p in artifacts}}
    output["passed"] = (not self_blocked and all(c["passed"] for c in cases) and aa_zero
                        and all(s["passed"] for s in steps + trap_steps)
                        and all(v["blocked"] == ["integrity"] for v in hidden_like.values()))
    write_report(Path("reports/advanced_verification.json"), output)
    print("Advanced verification:", output["passed"], output["run_id"], flush=True)
    raise SystemExit(0 if output["passed"] else 1)


if __name__ == "__main__":
    main()
